import{B as e,Q as t,s as n,z as r}from"./chunks/framework.hue4hZNP.js";import"./chunks/league-creation.DGW7vZUh.js";import"./chunks/league-draft-room.BVEE_9Yd.js";import"./chunks/league-standings.BQCrilVE.js";var i=JSON.parse(`{"title":"Run a League (Commissioner's Guide)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/run-a-league.md","filePath":"guide/run-a-league.md"}`),a={name:`guide/run-a-league.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="run-a-league-commissioner-s-guide" tabindex="-1">Run a League (Commissioner&#39;s Guide) <a class="header-anchor" href="#run-a-league-commissioner-s-guide" aria-label="Permalink to &quot;Run a League (Commissioner&#39;s Guide)&quot;">​</a></h1><p>A commissioner&#39;s guide to leagues — the multiplayer mode where players draft wrestlers and compete on shared shows. Written for the player who <em>creates</em> the league; players who join only need <a href="./report-match-results.html">Report Match Results</a>.</p><p><strong>The commissioner&#39;s arc:</strong> create the league → invite players → run the snake draft → book and settle matches → hand out the crown.</p><hr><h2 id="step-1-—-create-the-league" tabindex="-1">Step 1 — Create the league <a class="header-anchor" href="#step-1-—-create-the-league" aria-label="Permalink to &quot;Step 1 — Create the league&quot;">​</a></h2><p>Open <strong>Leagues</strong> from the navigation and create a new league. You become its <strong>commissioner</strong> automatically. Key settings:</p><ul><li><strong>Name</strong> — what players see on join.</li><li><strong>Max picks per player</strong> — how many wrestlers each player drafts.</li><li><strong>Duration</strong> — how many weeks the season runs.</li></ul><p><img src="/screenshots/league-creation.png" alt="League creation"></p><p>The league starts in <strong>Pre-Draft</strong> status — nobody picks yet.</p><hr><h2 id="step-2-—-invite-the-players" tabindex="-1">Step 2 — Invite the players <a class="header-anchor" href="#step-2-—-invite-the-players" aria-label="Permalink to &quot;Step 2 — Invite the players&quot;">​</a></h2><p>From the league&#39;s row on the Leagues page, click the <strong>invite link</strong> button. The invite dialog generates a shareable link — send it to your players.</p><p>Anyone opening the link either signs in or creates an account, then lands in your league. When everyone you want is in, move to the draft.</p><hr><h2 id="step-3-—-start-the-snake-draft" tabindex="-1">Step 3 — Start the snake draft <a class="header-anchor" href="#step-3-—-start-the-snake-draft" aria-label="Permalink to &quot;Step 3 — Start the snake draft&quot;">​</a></h2><p>As commissioner, start the draft once all players have joined. The draft snake-sequenced order: player 1, 2, 3, … then back 3, 2, 1 — so nobody gets a permanent first-pick advantage.</p><p>On the <strong>Draft</strong> page:</p><ul><li>The UI shows whose turn it is and the available wrestler pool.</li><li>On your turn, click <strong>Pick</strong> next to your wrestler.</li><li>Picks are live — everyone sees the board update as each player picks.</li></ul><p><img src="/screenshots/league-draft-room.png" alt="The Draft Room"></p><p>When every player has their full slate of picks, the league flips to <strong>Season Active</strong> and match booking begins.</p><hr><h2 id="step-4-—-book-and-settle-matches" tabindex="-1">Step 4 — Book and settle matches <a class="header-anchor" href="#step-4-—-book-and-settle-matches" aria-label="Permalink to &quot;Step 4 — Book and settle matches&quot;">​</a></h2><p>League matches live on shows. When a match between two league wrestlers is booked on a show assigned to the league:</p><ul><li>Each involved player gets an <strong>inbox notification</strong> asking them to report the result.</li><li>Players pick the winner in the report dialog (<a href="./report-match-results.html">Report Match Results</a> covers their side).</li><li>Reported results flow into the standings immediately.</li></ul><p>You book league shows like any other — see <a href="./schedule-a-show.html">Schedule a Show</a>, and remember to attach the league on creation so its matches count.</p><hr><h2 id="step-5-—-watch-the-standings-crown-the-winner" tabindex="-1">Step 5 — Watch the standings, crown the winner <a class="header-anchor" href="#step-5-—-watch-the-standings-crown-the-winner" aria-label="Permalink to &quot;Step 5 — Watch the standings, crown the winner&quot;">​</a></h2><p>The league dashboard has three tabs:</p><ul><li><strong>Standings</strong> — wins, losses, and draws per wrestler, updating live as results come in.</li><li><strong>Rosters</strong> — every player&#39;s drafted wrestlers.</li><li><strong>Show History</strong> — every show and match result the league produced.</li></ul><p><img src="/screenshots/league-standings.png" alt="League standings"></p><p>When the season&#39;s matches are settled, the league closes out <strong>Completed</strong> and its history stays browsable.</p><hr><h2 id="commissioner-tips" tabindex="-1">Commissioner tips <a class="header-anchor" href="#commissioner-tips" aria-label="Permalink to &quot;Commissioner tips&quot;">​</a></h2><ul><li><strong>Report stalls kill leagues.</strong> Nudge players whose matches await results — standings can&#39;t settle until they report.</li><li><strong>Exclusions</strong> — you can bar specific wrestlers from the draft pool (e.g. champions held by the promotion) when configuring the league.</li><li><strong>Assign shows to the league</strong> — a show only counts for league standings if it was created with the league attached.</li></ul><hr><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./report-match-results.html">Report Match Results</a> — what your players do each match.</li><li><a href="./set-player-controlled-wrestler.html">Set a Player-Controlled Wrestler</a> — giving each player a wrestler outside the draft.</li><li>The auto-generated <a href="./leagues.html">Leagues Overview</a> documents every league screen.</li></ul>`,37)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};